mapper.update:
UPDATE news
SET
    caption = #{news.caption},
    content = #{news.content}

        ,linkUrl = #{news.linkUrl}


        ,imageUrl = #{news.imageUrl}


WHERE id = #{news.id}
  AND EXISTS (
      SELECT 1 FROM user actor
      WHERE actor.id = #{actorUserId} AND actor.level = 0
  )

mapper.delete:
DELETE FROM news
WHERE id = #{id}
  AND EXISTS (
      SELECT 1 FROM user actor
      WHERE actor.id = #{actorUserId} AND actor.level = 0
  )
